/**
 * @name Tainted template data reaching eval/exec in Jinja2
 * @description Detects flows from template data into Python eval/exec in Jinja2 internals
 * @kind path-problem
 * @problem.severity error
 * @id py/jinja2/template-data-to-eval
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module TemplateDataToEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(API::CallNode renderCall |
      renderCall = API::moduleImport("jinja2.environment").getMember(["Template", "Environment"]).getACall() and
      source = renderCall.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["eval", "exec"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module TemplateDataToEvalFlow = TaintTracking::Global<TemplateDataToEvalConfig>;
import TemplateDataToEvalFlow::PathGraph

from TemplateDataToEvalFlow::PathNode source, TemplateDataToEvalFlow::PathNode sink
where TemplateDataToEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Template data flows into eval/exec here from $@.", source.getNode(), "template data"

/**
 * @name Insecure use of subprocess or os.system in Jinja2 internals
 * @description Detects calls to subprocess and os.system that may be influenced by template data
 * @kind path-problem
 * @problem.severity error
 * @id py/jinja2/command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module TemplateDataToCommandConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(API::CallNode renderCall |
      renderCall = API::moduleImport("jinja2.environment").getMember(["Template", "Environment"]).getACall() and
      source = renderCall.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("os").getMember("system").getACall() or
        call = API::moduleImport("subprocess").getMember(["Popen", "call", "run", "check_call", "check_output"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module TemplateDataToCommandFlow = TaintTracking::Global<TemplateDataToCommandConfig>;
import TemplateDataToCommandFlow::PathGraph

from TemplateDataToCommandFlow::PathNode source, TemplateDataToCommandFlow::PathNode sink
where TemplateDataToCommandFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Template data flows into a system command here from $@.", source.getNode(), "template data"

/**
 * @name Insecure file system access influenced by template data in Jinja2
 * @description Detects flows from template data into file open and path operations in Jinja2 internals
 * @kind path-problem
 * @problem.severity warning
 * @id py/jinja2/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module TemplateDataToFileConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(API::CallNode renderCall |
      renderCall = API::moduleImport("jinja2.environment").getMember(["Template", "Environment"]).getACall() and
      source = renderCall.getArg(0)
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("open").getACall() or
        call = API::moduleImport("os").getMember(["open", "remove", "unlink"]).getACall() or
        call = API::moduleImport("os.path").getMember(["join", "exists", "isfile", "isdir"]).getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module TemplateDataToFileFlow = TaintTracking::Global<TemplateDataToFileConfig>;
import TemplateDataToFileFlow::PathGraph

from TemplateDataToFileFlow::PathNode source, TemplateDataToFileFlow::PathNode sink
where TemplateDataToFileFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Template data flows into a file system operation here from $@.", source.getNode(), "template data"
